  (function(){"use strict";
  function D(s){return atob(s)}
  function E(s){return btoa(s).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'')}
  var WS_BASE="wss://"+location.host+"/api/";
  var SRCH_GOOGLE="https://www.google.com/search?q=%S";
  var LS_SC="zaka13_shortcuts_v3";
  var LS_NET="zaka13_872_server";
  var LS_SE="zaka13_search_engine";
  var EDU_DEF="education://settings";
  var P50000="50000";
  var P50001="50001";
  var P50002="50002";
  var GAMEURL="https://zakon.top/g.html";
  var A1URL="https://ap1.zaka13.com";
  var NPROOT="https://zakon.top/np/";
  var WS_CFG="https://raw.githubusercontent.com/lightspedfr/zakastatic/refs/heads/main/w.json";
  var LOGO_URL=D("aHR0cHM6Ly9jZG4uanNkZWxpdnIubmV0L2doL2xpZ2h0c3BlZGZyL3pha2FzdGF0aWNAbWFpbi9kYXRhbGlzdC54bWw=");
  var DEF_SHORTCUTS=[
  {name:"YouTube",url:"https://youtube.com",icon:"fa-solid fa-globe"},
  {name:"GitHub",url:"https://github.com",icon:"fa-solid fa-globe"},
  {name:"Discord",url:"https://discord.com",icon:"fa-solid fa-globe"},
  {name:"Twitter",url:"https://twitter.com",icon:"fa-solid fa-globe"},
  {name:"Reddit",url:"https://reddit.com",icon:"fa-solid fa-globe"},
  {name:"Spotify",url:"https://spotify.com",icon:"fa-solid fa-globe"},
  {name:"Netflix",url:"https://netflix.com",icon:"fa-solid fa-globe"},
  {name:"Twitch",url:"https://twitch.tv",icon:"fa-solid fa-globe"},
  {name:"Gmail",url:"https://mail.google.com",icon:"fa-solid fa-globe"}
  ];
  var tabMap=new Map();
  var activeId=null;
  var idCounter=0;
  var netAddr=(function(){try{var v=localStorage.getItem(LS_NET);return v?D(v):WS_BASE}catch(e){return WS_BASE}})();
  var srchUrl=(function(){try{var v=localStorage.getItem(LS_SE);return v?D(v):SRCH_GOOGLE}catch(e){return SRCH_GOOGLE}})();
  var shortcuts=(function(){try{var v=localStorage.getItem(LS_SC);return v?JSON.parse(D(v)):DEF_SHORTCUTS.slice()}catch(e){return DEF_SHORTCUTS.slice()}})();
  var tabBar=document.getElementById("c9d0e");
  var viewRoot=document.getElementById("h7i8j");
  var addrInput=document.getElementById("t3u4v");
  var plusBtn=document.getElementById("u1v2w");
  var backBtn=document.getElementById("d7e8f");
  var fwdBtn=document.getElementById("g9h0i");
  var reloadBtn=document.getElementById("q1r2s");
  var starBtn=document.getElementById("w5x6y");
  var settingsBtn=document.getElementById("sidebar-settings");
  var overlay=document.getElementById("e28IB");
  var overlayTimer=null;
  function showLoad(){if(overlayTimer){clearTimeout(overlayTimer);overlayTimer=null}overlay.classList.add("active");overlayTimer=setTimeout(function(){overlay.classList.remove("active");overlayTimer=null},700)}
  function hideLoad(){if(overlayTimer){clearTimeout(overlayTimer);overlayTimer=null}overlay.classList.remove("active")}
  function favCandidates(u){try{if(!/^https?:\/\//i.test(u))return[];var h=new URL(u).host;if(!h)return[];var hosts=[h];if(h.indexOf("www.")!==0&&h.split(".").length<=2)hosts.unshift("www."+h);var out=[];["ico","png"].forEach(function(ext){hosts.forEach(function(host){out.push(NPROOT+"https://"+host+"/favicon."+ext)})});return out}catch(x){return[]}}
  function loadFav(img,u,onFail){var list=favCandidates(u);var i=0;function next(){if(i>=list.length){img.onerror=null;if(onFail)onFail();return}img.src=list[i++]}img.onerror=next;next()}
  function applyFav(tab,u){if(!tab||!tab.favIcon)return;var img=tab.favIcon;if(!favCandidates(u).length){img.style.display="none";return}img.style.display="block";loadFav(img,u,function(){img.style.display="none"})}
  function clearFav(tab){if(!tab||!tab.favIcon)return;tab.favIcon.removeAttribute("src");tab.favIcon.onerror=null;tab.favIcon.style.display="none"}
  function buildProxyUrl(target){if(!/^https?:\/\//i.test(target)){target="https://"+target}var w1=E(netAddr);var go=E(target);return LOGO_URL+"?w1="+w1+"&go="+go}
  function normalizeInput(v){var s=v.trim();if(!s)return null;if(/^https?:\/\//i.test(s)||(s.indexOf(".")!==-1&&s.indexOf(" ")===-1)){return s.indexOf("http")===0?s:"https://"+s}return srchUrl.replace("%s",encodeURIComponent(s))}
  function buildSettings(tab){var root=document.createElement("div");root.className="i5j6k";var wrap=document.createElement("div");wrap.className="l7m8n";var hd=document.createElement("div");hd.className="o9p0q";var back=document.createElement("button");back.className="r1s2t";back.type="button";back.innerHTML='<i class="fa-solid fa-arrow-left"><\/i>';back.addEventListener("click",function(){tab.url="";tab.title.textContent="n3w t3b";showNewTab(tab);activateTab(tab.id);addrInput.value="";document.getElementById("p5q6r").innerHTML='<i class="fa-solid fa-globe"><\/i>';clearFav(tab)});var tt=document.createElement("div");tt.className="u3v4w";tt.textContent="s3ttin7gs";hd.appendChild(back);hd.appendChild(tt);
  var secNet=document.createElement("div");secNet.className="x5y6z";var hNet=document.createElement("div");hNet.className="a7b8c";hNet.textContent="Network";var rNet=document.createElement("div");rNet.className="d9e0f";var lNet=document.createElement("div");lNet.className="g1h2i";lNet.innerHTML='<div class="j3k4l">_872<\/div><div class="m5n6o">self explanitory<\/div>';var inpNet=document.createElement("input");inpNet.className="p7q8r";inpNet.type="text";inpNet.value=netAddr;inpNet.placeholder="wss://_872.example.com/api/";rNet.appendChild(lNet);rNet.appendChild(inpNet);secNet.appendChild(hNet);secNet.appendChild(rNet);
  var secSrch=document.createElement("div");secSrch.className="x5y6z";var hSrch=document.createElement("div");hSrch.className="a7b8c";hSrch.textContent="Search";var rSrch=document.createElement("div");rSrch.className="d9e0f";var lSrch=document.createElement("div");lSrch.className="g1h2i";lSrch.innerHTML='<div class="j3k4l">search engine<\/div><div class="m5n6o"><\/div>';var selSrch=document.createElement("select");selSrch.className="s9t0u";var engs=[{v:"https://www.google.com/search?q=%S",n:"Google"},{v:"https://www.bing.com/search?q=%S",n:"Bing"},{v:"https://duckduckgo.com/?q=%S",n:"DuckDuckGo"},{v:"https://search.brave.com/search?q=%S",n:"Brave"}];engs.forEach(function(o){var op=document.createElement("option");op.value=o.v;op.textContent=o.n;if(o.v===srchUrl)op.selected=true;selSrch.appendChild(op)});rSrch.appendChild(lSrch);rSrch.appendChild(selSrch);secSrch.appendChild(hSrch);secSrch.appendChild(rSrch);
  var secAct=document.createElement("div");secAct.className="x5y6z";var hAct=document.createElement("div");hAct.className="a7b8c";hAct.textContent="Actions";var rAct=document.createElement("div");rAct.className="d9e0f";var lAct=document.createElement("div");lAct.className="g1h2i";lAct.innerHTML='<div class="j3k4l">Save settings<\/div><div class="m5n6o">apply + refresh stuff + save changes<\/div>';var saveBtn=document.createElement("button");saveBtn.className="v1w2x";saveBtn.type="button";saveBtn.textContent="Save";saveBtn.addEventListener("click",function(){var v=inpNet.value.trim();if(v&&v.indexOf("wss://")===0){netAddr=v;try{localStorage.setItem(LS_NET,E(v))}catch(e){}}srchUrl=selSrch.value;try{localStorage.setItem(LS_SE,E(srchUrl))}catch(e){}saveBtn.textContent="Saved";setTimeout(function(){saveBtn.textContent="Save"},1200)});rAct.appendChild(lAct);rAct.appendChild(saveBtn);secAct.appendChild(hAct);secAct.appendChild(rAct);
  wrap.appendChild(hd);wrap.appendChild(secNet);wrap.appendChild(secSrch);wrap.appendChild(secAct);root.appendChild(wrap);root.__872Input=inpNet;root._searchSelect=selSrch;return root}
  function renderShortcuts(container,tab){container.innerHTML="";shortcuts.forEach(function(s){var t=document.createElement("div");t.className="z9a0b";t.title=s.url;var ic=document.createElement("div");ic.className="c1d2e";var fi=document.createElement("i");fi.className=s.icon||"fa-solid fa-globe";var tileImg=document.createElement("img");tileImg.alt="";tileImg.draggable=false;tileImg.style.cssText="width:32px;height:32px;object-fit:contain;display:block";ic.appendChild(fi);if(favCandidates(s.url).length){tileImg.onload=function(){if(fi.parentNode===ic)ic.replaceChild(tileImg,fi)};loadFav(tileImg,s.url,null)}var nm=document.createElement("div");nm.className="f3g4h";nm.textContent=s.name;t.appendChild(ic);t.appendChild(nm);t.addEventListener("click",function(){if(!tab)return;tab.url=s.url;tab.title.textContent=s.name;hideNewTab(tab);activateTab(tab.id);openUrl(s.url,tab.id)});container.appendChild(t)});var dc=document.createElement("a");dc.className="discord-link";dc.href="https://discord.gg/Y26EUssP3";dc.target="_blank";dc.rel="noopener noreferrer";var dci=document.createElement("img");dci.src="data:image/svg+xml;base64,";dci.alt="discord";dc.appendChild(dci);var dcs=document.createElement("span");dcs.textContent="join the discord";dc.appendChild(dcs);container.appendChild(dc)}
  function createTab(startUrl){var id=++idCounter;var tabEl=document.createElement("div");tabEl.className="f1g2h";var ic=document.createElement("span");ic.className="l5m6n";ic.innerHTML='<i class="fa-regular fa-window-maximize"><\/i>';var label=document.createElement("span");label.className="o7p8q";label.textContent=startUrl||"n3w t3b";var close=document.createElement("button");close.className="r9s0t";close.type="button";close.title="y2c5d";close.innerHTML='<i class="fa-solid fa-xmark"><\/i>';close.onclick=function(ev){ev.stopPropagation();closeTab(id)};tabEl.appendChild(ic);var fi=document.createElement("img");fi.className="tab-favicon";fi.alt="";fi.style.display="none";fi.draggable=false;fi.width=64;fi.height=64;tabEl.appendChild(fi);tabEl.appendChild(label);tabEl.appendChild(close);tabEl.onclick=function(){activateTab(id)};var fr=document.createElement("iframe");fr.className="k9l0m";fr.setAttribute("sandbox","allow-same-origin allow-scripts allow-popups allow-forms allow-modals");var nt=document.createElement("div");nt.className="q3r4s";var svgNS="http://www.w3.org/2000/svg";var svg=document.createElementNS(svgNS,"svg");svg.setAttribute("class","t5u6v");svg.setAttribute("viewBox","0 0 60 20");var rect=document.createElementNS(svgNS,"rect");rect.setAttribute("width","100%");rect.setAttribute("height","100%");rect.setAttribute("fill","#000");rect.setAttribute("rx","4");var txt=document.createElementNS(svgNS,"text");txt.setAttribute("x","50%");txt.setAttribute("y","55%");txt.setAttribute("fill","#fff");txt.setAttribute("font-family","system-ui,sans-serif");txt.setAttribute("font-size","12");txt.setAttribute("font-weight","600");txt.setAttribute("text-anchor","middle");txt.setAttribute("dominant-baseline","middle");txt.setAttribute("letter-spacing","0.5");txt.textContent="zaka";svg.appendChild(rect);svg.appendChild(txt);var grid=document.createElement("div");grid.className="w7x8y";nt.appendChild(svg);nt.appendChild(grid);tabBar.insertBefore(tabEl,plusBtn);viewRoot.appendChild(fr);viewRoot.appendChild(nt);var tab={id:id,el:tabEl,frame:fr,title:label,favIcon:fi,url:startUrl||"",newTab:nt,settings:null,grid:grid,net:netAddr};tabMap.set(id,tab);renderShortcuts(grid,tab);activateTab(id);if(startUrl){if(startUrl===EDU_DEF||startUrl===P50000||startUrl===P50001||startUrl===P50002){openSettings(tab)}else{openUrl(startUrl,id)}}return id}
  function closeTab(id){var t=tabMap.get(id);if(!t)return;var wasActive=activeId===id;t.el.remove();t.frame.remove();if(t.newTab)t.newTab.remove();if(t.settings)t.settings.remove();tabMap.delete(id);if(tabMap.size===0){createTab();return}if(wasActive){var keys=Array.from(tabMap.keys());var idx=keys.indexOf(id);var next=keys[Math.max(0,idx-1)];activateTab(next)}}
  function activateTab(id){var t=tabMap.get(id);if(!t)return;tabMap.forEach(function(o){o.el.classList.remove("i3j4k");o.frame.classList.remove("n1o2p");if(o.newTab)o.newTab.style.display="none";if(o.settings)o.settings.classList.remove("n1o2p")});t.el.classList.add("i3j4k");activeId=id;if(t.url===EDU_DEF||t.url===P50000||t.url===P50001||t.url===P50002){openSettings(t)}else if(t.url){t.frame.classList.add("n1o2p");addrInput.value=t.url;document.getElementById("p5q6r").innerHTML='<i class="fa-solid fa-lock"><\/i>'}else{if(t.newTab)t.newTab.style.display="flex";addrInput.value="";document.getElementById("p5q6r").innerHTML='<i class="fa-solid fa-globe"><\/i>'}}
  function hideNewTab(t){if(t.newTab)t.newTab.style.display="none";t.frame.classList.remove("n1o2p");if(t.settings)t.settings.classList.remove("n1o2p")}
  function showNewTab(t){if(t.newTab)t.newTab.style.display="flex";if(t.settings)t.settings.classList.remove("n1o2p")}
  function openSettings(t){if(!t.settings){t.settings=buildSettings(t);viewRoot.appendChild(t.settings)}else{if(t.settings.__872Input)t.settings.__872Input.value=netAddr;if(t.settings._searchSelect)t.settings._searchSelect.value=srchUrl}tabMap.forEach(function(o){o.frame.classList.remove("n1o2p");if(o.newTab)o.newTab.style.display="none";if(o.settings)o.settings.classList.remove("n1o2p")});t.settings.classList.add("n1o2p");t.frame.classList.remove("n1o2p");if(t.newTab)t.newTab.style.display="none";addrInput.value=EDU_DEF;t.url=EDU_DEF;t.title.textContent="s3ttin7gs";document.getElementById("p5q6r").innerHTML='<i class="fa-solid fa-gear"><\/i>';activeId=t.id}
  function openUrl(target,id){var t=tabMap.get(id);if(!t)return;hideNewTab(t);var proxy=buildProxyUrl(target);t.frame.src=proxy;t.url=target;addrInput.value=target;document.getElementById("p5q6r").innerHTML='<i class="fa-solid fa-lock"><\/i>';try{var host=new URL(target).hostname;t.title.textContent=host}catch(e){t.title.textContent=target}t.frame.classList.add("n1o2p");applyFav(t,target)}
  function testWs(url,cb){var ws;try{ws=new WebSocket(url)}catch(e){cb(false);return}var done=false;var to=setTimeout(function(){if(!done){done=true;try{ws.close()}catch(e){}cb(false)}},3000);ws.onopen=function(){if(done)return;done=true;clearTimeout(to);try{ws.close()}catch(e){}cb(true)};ws.onerror=function(){if(done)return;done=true;clearTimeout(to);cb(false)};ws.onclose=function(){if(done)return;done=true;clearTimeout(to);cb(false)}}
  function fetchWs(cb){fetch(WS_CFG).then(function(r){return r.json()}).then(function(d){if(!d||!d.ws||!d.ws.length){cb(null);return}var arr=d.ws.slice();var i=0;function tryNext(){if(i>=arr.length){cb(null);return}var u=arr[i++];testWs(u,function(ok){if(ok){cb(u)}else{tryNext()}})}tryNext()}).catch(function(){cb(null)})}
  function startup(){fetchWs(function(w){if(w){netAddr=w;try{localStorage.setItem(LS_NET,E(w))}catch(e){}}createTab()})}
  addrInput.addEventListener("keydown",function(ev){if(ev.key==="Enter"){ev.preventDefault();var v=addrInput.value.trim();if(!v)return;var t=tabMap.get(activeId);if(!t)return;showLoad();if(v===EDU_DEF||v===P50000||v===P50001||v===P50002||v.indexOf("education://")===0){t.url=EDU_DEF;t.title.textContent="s3ttin7gs";openSettings(t);return}var tgt=normalizeInput(v);if(!tgt)return;t.url=tgt;t.title.textContent=tgt.replace(/^https?:\/\//,"").split("/")[0]||v;hideNewTab(t);openUrl(tgt,activeId)}});
  plusBtn.onclick=function(){createTab()};
  backBtn.onclick=function(){var t=tabMap.get(activeId);if(!t)return;if(t.url===EDU_DEF||t.url===P50000||t.url===P50001||t.url===P50002){t.url="";t.title.textContent="n3w t3b";showNewTab(t);activateTab(t.id);addrInput.value="";document.getElementById("p5q6r").innerHTML='<i class="fa-solid fa-globe"><\/i>';clearFav(t);return}try{t.frame.contentWindow.history.back()}catch(e){}};
  fwdBtn.onclick=function(){var t=tabMap.get(activeId);if(!t)return;try{t.frame.contentWindow.history.forward()}catch(e){}};
  reloadBtn.onclick=function(){var t=tabMap.get(activeId);if(!t)return;if(t.url===EDU_DEF||t.url===P50000||t.url===P50001||t.url===P50002){openSettings(t)}else if(t.url){openUrl(t.url,activeId)}};
  starBtn.onclick=function(){var i=starBtn.querySelector("i");i.classList.toggle("fa-regular");i.classList.toggle("fa-solid")};
  settingsBtn.onclick=function(){var t=tabMap.get(activeId);if(!t)return;t.url=EDU_DEF;t.title.textContent="s3ttin7gs";openSettings(t)};
  function sideOpen(url,name){var id=createTab(url);var t=tabMap.get(id);if(t)t.title.textContent=name}
  document.getElementById("sidebar-game").addEventListener("click",function(){sideOpen(GAMEURL,"g@mez")});
  document.getElementById("sidebar-a1").addEventListener("click",function(){sideOpen(A1URL,"A1")});
  startup()})();
